{
  "items": [
    {
      "name": "MvPolynomial.finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) →\n  [inst : CommSemiring R] → (n : ℕ) → MvPolynomial (Fin (n + 1)) R ≃ₐ[R] Polynomial (MvPolynomial (Fin n) R)"
    },
    {
      "name": "MvPolynomial.pUnitAlgEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) → [inst : CommSemiring R] → MvPolynomial PUnit.{u_2 + 1} R ≃ₐ[R] Polynomial R"
    },
    {
      "name": "MvPolynomial.optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) → (S₁ : Type v) → [inst : CommSemiring R] → MvPolynomial (Option S₁) R ≃ₐ[R] Polynomial (MvPolynomial S₁ R)"
    },
    {
      "name": "MvPolynomial.rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {τ : Type u_2} → {R : Type u_4} → [inst : CommSemiring R] → (σ → τ) → MvPolynomial σ R →ₐ[R] MvPolynomial τ R"
    },
    {
      "name": "MvPolynomial.rename_X",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ) (i : σ),\n  (MvPolynomial.rename f) (MvPolynomial.X i) = MvPolynomial.X (f i)"
    },
    {
      "name": "Polynomial.toMvPolynomial_eq_rename_comp",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_3} [inst : CommSemiring R] (i : σ),\n  Polynomial.toMvPolynomial i = (MvPolynomial.rename fun x => i).comp ↑(MvPolynomial.pUnitAlgEquiv R).symm"
    },
    {
      "name": "MvPolynomial.rename_toMvPolynomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_3} {τ : Type u_4} [inst : CommSemiring R] (f : σ → τ) (a : σ) (p : Polynomial R),\n  (MvPolynomial.rename f) ((Polynomial.toMvPolynomial a) p) = (Polynomial.toMvPolynomial (f a)) p"
    },
    {
      "name": "MvPolynomial.rename_comp_toMvPolynomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_3} {τ : Type u_4} [inst : CommSemiring R] (f : σ → τ) (a : σ),\n  (MvPolynomial.rename f).comp (Polynomial.toMvPolynomial a) = Polynomial.toMvPolynomial (f a)"
    }
  ]
}
